RETURNS TIMESTAMPTZ
LANGUAGE sql
IMMUTABLE
SECURITY INVOKER
SET search_path = ''
AS $$
    SELECT date_trunc('week', p_now AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
